 if(path==='/api/access-requests'&&method==='POST'){let x=await body(req),groupId=String(x.groupId||''),kind=String(x.kind||''),name=String(x.name||'').trim().slice(0,70),username=String(x.username||'').trim().toLowerCase().slice(0,40),email=String(x.email||'').trim().toLowerCase().slice(0,120),phone=String(x.phone||'').replace(/\D/g,'').slice(0,20),message=String(x.message||'').trim().slice(0,500);if(!['player_signup','password_reset'].includes(kind)||!name||!email&&!phone||email&&!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)||phone&&phone.length<10)return err('Choose a venue and enter your name and a valid email or phone number.');if(!await db.prepare('SELECT id FROM groups WHERE id=?').bind(groupId).first())return err('Choose a valid venue.');let recent=await db.prepare('SELECT COUNT(*) AS n FROM access_requests WHERE group_id=? AND created_at>? AND (email=? OR phone=?)').bind(groupId,now()-86400000,email,phone).first();if(recent.n>=3)return err('Your request was already received. Please wait for the administrator.',429);let volume=await db.prepare('SELECT COUNT(*) AS n FROM access_requests WHERE group_id=? AND created_at>?').bind(groupId,now()-86400000).first();if(volume.n>=100)return err('This venue cannot receive more requests today. Contact its administrator.',429);await db.prepare('INSERT INTO access_requests (id,group_id,kind,name,username,email,phone,message,status,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)').bind(id(),groupId,kind,name,username,email,phone,message,'pending',now(),now()).run();return json({ok:true},201)}
 if(path==='/api/login'&&method==='POST'){await ensureOwner(db,env);let x=await body(req),identifier=String(x.identifier||'').trim().toLowerCase(),phone=identifier.replace(/\D/g,'');let a=await db.prepare('SELECT * FROM accounts WHERE active=1 AND (username=? OR email=? OR phone=?)').bind(identifier,identifier,phone).first();if(!a||!equal(await hash(String(x.password||''),a.salt),a.password_hash))return err('Username, email, phone, or password is incorrect.',401);if(isOwnerAccount(a))a.mustChangePassword=!!(await db.prepare('SELECT must_change_password FROM owner_security WHERE account_id=?').bind(a.id).first())?.must_change_password;let session=await issue(db,a),headers=new Headers({'content-type':'application/json'});headers.append('set-cookie',setCookie(session.token));if(isOwnerAccount(a))headers.append('set-cookie',setCookie(session.token,'osp_owner_session'));return new Response(JSON.stringify({account:session.account}),{headers})}
 let a=await account(req,db,path.startsWith('/api/owner/'));if(path==='/api/session'&&method==='GET')return json({account:a?publicAccount(a):null});if(!a)return err('Sign in to continue.',401);let previewGroup='';if(isOwnerAccount(a)){previewGroup=String(req.headers.get('x-osp-venue')||'');if(previewGroup){if(previewGroup===OWNER_GROUP||!await db.prepare('SELECT id FROM groups WHERE id=?').bind(previewGroup).first())return err('Venue not found.',404)}}
