export default {async fetch(req,env){let url=new URL(req.url),path=url.pathname;try{if(path.startsWith('/api/'))return await api(req,env,path);if(req.method!=='GET'&&req.method!=='HEAD')return err('Method not allowed.',405);let file=files[path]||files[path==='/'?'/index.html':''];if(!file)return new Response('Not found',{status:404});return new Response(file.binary?Uint8Array.from(atob(file.body),c=>c.charCodeAt(0)):file.body,{headers:{'content-type':file.type,'cache-control':(path==='/'||/\.(html|js|css)$/.test(path))?'no-store':'public, max-age=3600'}})}catch(e){if(String(e.message).includes('UNIQUE constraint'))return err('Username, email, or phone is already in use.',409);console.error(e);return err(e.message==='Request too large'?e.message:'Unable to complete the request.',e.message==='Request too large'?413:500)}}};
